mapper.select:
SELECT ac.*, am.model_name AS modelName, aa.agent_name AS agentName, ap.prompt_title AS promptTitle FROM AI_CONVERSATION ac LEFT JOIN AI_MODEL am ON ac.model_key = am.model_key LEFT JOIN AI_AGENT aa ON ac.agent_key = aa.agent_key LEFT JOIN AI_PROMPT ap ON ac.prompt_key = ap.prompt_key WHERE 1=1
AND ac.env_code = #{req.envCode}
AND ac.memory_id = #{req.memoryKey}
AND ac.role = #{req.role}
ORDER BY ac.create_time DESC

SELECT ac.*, am.model_name AS modelName, aa.agent_name AS agentName, ap.prompt_title AS promptTitle FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY ac.memory_key ORDER BY ac.update_time DESC) AS rn FROM AI_CONVERSATION ac WHERE 1=1
AND ac.env_code = #{req.envCode}
AND ac.memory_id = #{req.memoryKey}
AND ac.role = #{req.role}
) ac LEFT JOIN AI_MODEL am ON ac.model_key = am.model_key LEFT JOIN AI_AGENT aa ON ac.agent_key = aa.agent_key LEFT JOIN AI_PROMPT ap ON ac.prompt_key = ap.prompt_key WHERE ac.rn = 1 ORDER BY ac.create_time DESC
